'use client'
import { useState, useMemo } from 'react'
import Image from 'next/image'
import { PRODUCTS, CATEGORIES, formatPrice } from '@/lib/products'
import CartDrawer from '@/components/ordering/CartDrawer'
import CheckoutForm from '@/components/ordering/CheckoutForm'

const COOKING_CATS = ['Clásicas', 'Especiales', 'Combos']

function cartKey(productId, cookingMethod) {
  return cookingMethod ? `${productId}_${cookingMethod}` : productId
}

export default function PedirPage() {
  const [cart, setCart] = useState([])
  const [activeCategory, setActiveCategory] = useState('Clásicas')
  const [cartOpen, setCartOpen] = useState(false)
  const [step, setStep] = useState('menu')
  const [order, setOrder] = useState(null)

  const cartCount = cart.reduce((s, i) => s + i.qty, 0)
  const cartTotal = cart.reduce((s, i) => s + i.price * i.qty, 0)

  function addToCart(product, cookingMethod = null) {
    const key = cartKey(product.id, cookingMethod)
    setCart(prev => {
      const existing = prev.find(i => i.key === key)
      if (existing) return prev.map(i => i.key === key ? { ...i, qty: i.qty + 1 } : i)
      return [...prev, { ...product, qty: 1, key, cooking_method: cookingMethod }]
    })
  }

  function removeFromCart(key) {
    setCart(prev => {
      const item = prev.find(i => i.key === key)
      if (!item) return prev
      if (item.qty === 1) return prev.filter(i => i.key !== key)
      return prev.map(i => i.key === key ? { ...i, qty: i.qty - 1 } : i)
    })
  }

  function getQty(key) {
    return cart.find(i => i.key === key)?.qty || 0
  }

  const filtered = useMemo(() => PRODUCTS.filter(p => p.category === activeCategory), [activeCategory])

  if (step === 'success') {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center px-4">
        <div className="text-center max-w-md">
          <div className="text-8xl mb-6">🎉</div>
          <h1 className="text-4xl font-extrabold text-cream mb-3">¡Pedido recibido!</h1>
          <p className="text-gray-400 text-lg mb-2">
            Hola <span className="text-orange-400 font-semibold">{order?.customer_name}</span>, tu pedido fue registrado.
          </p>
          <p className="text-gray-500 mb-2">Te avisamos al <span className="text-cream">{order?.customer_email}</span> cuando esté listo.</p>
          <p className="text-orange-500 font-bold text-xl mb-10">Total: {formatPrice(order?.total)}</p>
          <button
            onClick={() => { setCart([]); setStep('menu') }}
            className="bg-orange-500 hover:bg-orange-600 text-black font-extrabold py-4 px-10 rounded-full text-lg transition-all hover:scale-105"
          >
            Hacer otro pedido
          </button>
        </div>
      </div>
    )
  }

  if (step === 'checkout') {
    return (
      <div className="min-h-screen bg-black py-24 px-4">
        <CheckoutForm
          cart={cart}
          onBack={() => setStep('menu')}
          onSuccess={data => { setOrder(data); setStep('success') }}
        />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-black">
      {/* Header */}
      <div className="bg-[radial-gradient(ellipse_at_top,_rgba(255,102,0,0.18),_transparent_70%)] pt-28 pb-12 text-center px-4">
        <h1 className="text-5xl md:text-7xl font-extrabold mb-4">
          <span className="text-orange-500">Pedí</span>
          <span className="text-cream"> online</span>
        </h1>
        <p className="text-gray-400 text-lg">Elegí tus empanadas y confirmá tu pedido</p>
      </div>

      {/* Sticky bar: categorías + carrito */}
      <div className="sticky top-16 z-40 bg-black/95 backdrop-blur border-b border-gray-800 px-4">
        <div className="max-w-6xl mx-auto flex items-center gap-4 py-3 overflow-x-auto scrollbar-hide">
          <div className="flex gap-2 flex-1 min-w-0">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`whitespace-nowrap px-4 py-2 rounded-full text-sm font-semibold transition-all flex-shrink-0 ${
                  activeCategory === cat
                    ? 'bg-orange-500 text-black'
                    : 'border border-gray-700 text-gray-400 hover:border-orange-500 hover:text-orange-400'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
          {cartCount > 0 && (
            <button
              onClick={() => setCartOpen(true)}
              className="flex-shrink-0 flex items-center gap-2 bg-orange-500 hover:bg-orange-600 text-black font-bold px-4 py-2 rounded-full text-sm transition-all"
            >
              <span>🛒</span>
              <span>{cartCount}</span>
              <span>·</span>
              <span>{formatPrice(cartTotal)}</span>
            </button>
          )}
        </div>
      </div>

      {/* Grilla de productos */}
      <div className="max-w-6xl mx-auto px-4 py-10">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {filtered.map(product => {
            const hasCooking = COOKING_CATS.includes(product.category)
            const simpleQty = getQty(product.id)
            const hornoQty = getQty(cartKey(product.id, 'horno'))
            const fritasQty = getQty(cartKey(product.id, 'fritas'))
            const totalQty = hasCooking ? hornoQty + fritasQty : simpleQty

            return (
              <div
                key={product.id}
                className="bg-[#0d0d0d] border border-gray-800 hover:border-orange-500/60 rounded-2xl overflow-hidden flex flex-col transition-all group"
              >
                {/* Imagen */}
                <div className="relative h-44 bg-gray-900 overflow-hidden">
                  {product.img ? (
                    <Image
                      src={product.img}
                      alt={product.nombre}
                      fill
                      className="object-cover group-hover:scale-105 transition-transform duration-500"
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-7xl">{product.emoji}</div>
                  )}
                  {totalQty > 0 && (
                    <div className="absolute top-2 right-2 bg-orange-500 text-black text-xs font-extrabold w-6 h-6 rounded-full flex items-center justify-center shadow-lg">
                      {totalQty}
                    </div>
                  )}
                </div>

                {/* Info */}
                <div className="p-5 flex flex-col flex-1">
                  <h3 className="text-cream font-bold text-base mb-1">{product.nombre}</h3>
                  <p className="text-gray-500 text-sm flex-1 leading-relaxed">{product.desc}</p>

                  {hasCooking ? (
                    /* Selector por método de cocción */
                    <div className="mt-4">
                      <div className="flex items-center justify-between mb-2.5">
                        <span className="text-orange-500 font-extrabold text-lg">{formatPrice(product.price)}</span>
                        <span className="text-gray-600 text-xs">c/u</span>
                      </div>
                      <div className="space-y-2">
                        {[
                          ['horno', '♨️', 'Al horno', hornoQty],
                          ['fritas', '🔥', 'Fritas', fritasQty],
                        ].map(([method, icon, label, qty]) => (
                          <div key={method} className="flex items-center justify-between">
                            <span className="text-gray-400 text-xs font-medium">{icon} {label}</span>
                            {qty === 0 ? (
                              <button
                                onClick={() => addToCart(product, method)}
                                className="text-xs bg-orange-500/15 border border-orange-600/40 text-orange-400 hover:bg-orange-500/25 hover:border-orange-500 px-3 py-1.5 rounded-full font-semibold transition-all"
                              >
                                + Agregar
                              </button>
                            ) : (
                              <div className="flex items-center gap-1.5">
                                <button
                                  onClick={() => removeFromCart(cartKey(product.id, method))}
                                  className="w-6 h-6 rounded-full border border-gray-600 hover:border-orange-500 text-gray-300 hover:text-orange-500 font-bold flex items-center justify-center text-sm transition-colors"
                                >−</button>
                                <span className="text-cream font-bold w-5 text-center text-sm">{qty}</span>
                                <button
                                  onClick={() => addToCart(product, method)}
                                  className="w-6 h-6 rounded-full bg-orange-500 hover:bg-orange-600 text-black font-bold flex items-center justify-center text-sm transition-colors"
                                >+</button>
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  ) : (
                    /* Botón simple para el resto */
                    <div className="flex items-center justify-between mt-4">
                      <span className="text-orange-500 font-extrabold text-lg">{formatPrice(product.price)}</span>
                      {simpleQty === 0 ? (
                        <button
                          onClick={() => addToCart(product)}
                          className="bg-orange-500 hover:bg-orange-600 text-black font-bold px-5 py-2 rounded-full text-sm transition-all hover:scale-105"
                        >
                          Agregar
                        </button>
                      ) : (
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() => removeFromCart(product.id)}
                            className="w-8 h-8 rounded-full border border-gray-600 hover:border-orange-500 text-gray-300 hover:text-orange-500 font-bold flex items-center justify-center transition-colors"
                          >−</button>
                          <span className="text-cream font-bold w-6 text-center">{simpleQty}</span>
                          <button
                            onClick={() => addToCart(product)}
                            className="w-8 h-8 rounded-full bg-orange-500 hover:bg-orange-600 text-black font-bold flex items-center justify-center transition-colors"
                          >+</button>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* FAB carrito */}
      {cartCount > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 sm:hidden">
          <button
            onClick={() => setCartOpen(true)}
            className="bg-orange-500 hover:bg-orange-600 text-black font-extrabold px-8 py-4 rounded-full shadow-lg shadow-orange-500/30 flex items-center gap-3 text-base transition-all hover:scale-105"
          >
            <span>🛒</span>
            <span>{cartCount} {cartCount === 1 ? 'item' : 'items'}</span>
            <span>·</span>
            <span>{formatPrice(cartTotal)}</span>
          </button>
        </div>
      )}

      {cartOpen && (
        <CartDrawer
          cart={cart}
          onAdd={item => addToCart(item, item.cooking_method)}
          onRemove={removeFromCart}
          onClose={() => setCartOpen(false)}
          onCheckout={() => { setCartOpen(false); setStep('checkout') }}
        />
      )}
    </div>
  )
}
